//! Word lists used to decide whether the text being typed belongs to the
//! language of the active layout or to some other one.
//!
//! The files are plain UTF-8, one lowercase word per line, ordered by
//! frequency: the line number *is* the rank. They are downloaded and
//! regenerated by `tools/fetch-lexicons.ps1`.

use std::collections::HashMap;
use std::fs;
use std::path::Path;

/// How well a typed fragment looks like a word of a language.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Support {
    /// The fragment is a complete word, and this is its frequency rank.
    Exact { rank: u32 },
    /// The fragment starts at least one word, whose rank is given.
    Prefix { best_rank: u32 },
    /// No word in the language starts with this fragment.
    None,
}

impl Support {
    pub fn is_none(self) -> bool {
        matches!(self, Support::None)
    }
}

/// The frequency-ordered word list of one language.
pub struct Lexicon {
    /// Words sorted alphabetically; `ranks` keeps the frequency rank that the
    /// word had in the source file, so both queries can use a binary search.
    words: Vec<Box<str>>,
    ranks: Vec<u32>,
}

impl Lexicon {
    /// Parses `word\nword\n…`, where the position in the file is the rank.
    pub fn parse(text: &str) -> Self {
        let mut entries: Vec<(Box<str>, u32)> = text
            .lines()
            .enumerate()
            .filter_map(|(index, line)| {
                let word = line.trim();
                if word.is_empty() {
                    return None;
                }
                Some((word.to_lowercase().into_boxed_str(), index as u32 + 1))
            })
            .collect();

        entries.sort_unstable_by(|a, b| a.0.cmp(&b.0));

        let (words, ranks) = entries.into_iter().unzip();
        Self { words, ranks }
    }

    /// Rank of a complete word.
    fn exact_rank(&self, word: &str) -> Option<u32> {
        self.words
            .binary_search_by(|probe| (**probe).cmp(word))
            .ok()
            .map(|index| self.ranks[index])
    }

    /// Lowest rank among the words starting with `prefix`.
    ///
    /// The words sharing a prefix sit in one contiguous run of an alphabetically
    /// sorted list, so the run is found by a lower-bound search and then read
    /// to its end. The run cannot be found with `starts_with` directly:
    /// that predicate is false inside the run and true both before and after
    /// it, which is exactly the shape a binary search cannot handle.
    fn best_prefix_rank(&self, prefix: &str) -> Option<u32> {
        let start = self.words.partition_point(|word| &**word < prefix);
        let run = self.words[start..]
            .iter()
            .take_while(|word| word.starts_with(prefix))
            .count();

        self.ranks[start..start + run].iter().copied().min()
    }

    pub fn support(&self, word: &str) -> Support {
        let word = word.to_lowercase();

        if word.is_empty() {
            // An empty buffer matches every language equally well, which tells
            // the detector nothing at all.
            return Support::None;
        }

        if let Some(rank) = self.exact_rank(&word) {
            Support::Exact { rank }
        } else {
            match self.best_prefix_rank(&word) {
                Some(best_rank) => Support::Prefix { best_rank },
                None => Support::None,
            }
        }
    }

    pub fn len(&self) -> usize {
        self.words.len()
    }

    pub fn is_empty(&self) -> bool {
        self.words.is_empty()
    }
}

/// The languages that are currently installed next to the executable.
///
/// Keeping them on disk rather than compiled in means a new language is a
/// dropped-in file, and the binary does not grow by megabytes.
pub struct LexiconSet {
    languages: HashMap<String, Lexicon>,
}

impl LexiconSet {
    /// Loads `<dir>/<lang>.txt` for the given language tags, ignoring the ones
    /// that are missing or unreadable.
    pub fn load(dir: &Path, languages: &[&str]) -> Self {
        let mut languages_loaded = HashMap::new();

        for tag in languages {
            let path = dir.join(format!("{tag}.txt"));

            if let Ok(text) = fs::read_to_string(&path)
                && !text.trim().is_empty()
            {
                languages_loaded.insert((*tag).to_string(), Lexicon::parse(&text));
            }
        }

        Self {
            languages: languages_loaded,
        }
    }

    /// Builds a set from in-memory files, for tests. Blank entries are skipped
    /// just like missing ones.
    pub fn from_files(files: &[(&str, &str)]) -> Self {
        let mut languages = HashMap::new();
        for (tag, text) in files {
            if !text.trim().is_empty() {
                languages.insert((*tag).to_string(), Lexicon::parse(text));
            }
        }
        Self { languages }
    }

    pub fn contains(&self, language: &str) -> bool {
        self.languages.contains_key(language)
    }

    /// `Support::None` for a language without a word list: an unknown language
    /// must never look like a match.
    pub fn support(&self, language: &str, word: &str) -> Support {
        match self.languages.get(language) {
            Some(lexicon) => lexicon.support(word),
            None => Support::None,
        }
    }

    pub fn len(&self) -> usize {
        self.languages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.languages.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const EN: &str = "the\nof\nand\nto\nin\nyou\nit\nthat\nis\nwas\ntoday\nhello\n";
    const RU: &str = "и\nв\nне\nна\nя\nбыть\nпривет\nсегодня\nещё\nдом\n";

    #[test]
    fn exact_word_reports_its_rank() {
        let lexicon = Lexicon::parse(EN);

        assert_eq!(lexicon.support("the"), Support::Exact { rank: 1 });
        assert_eq!(lexicon.support("hello"), Support::Exact { rank: 12 });
    }

    #[test]
    fn a_word_prefix_is_reported_with_the_best_rank() {
        let lexicon = Lexicon::parse(EN);

        // "tod" starts "today" only, which is the 11th word of the list.
        assert_eq!(lexicon.support("tod"), Support::Prefix { best_rank: 11 });
        // "t" starts "the", "to" and "today"; the best of those is "the".
        assert_eq!(lexicon.support("t"), Support::Prefix { best_rank: 1 });
    }

    #[test]
    fn an_unknown_fragment_is_not_a_prefix_of_anything() {
        let lexicon = Lexicon::parse(EN);

        assert_eq!(lexicon.support("qqzz"), Support::None);
    }

    #[test]
    fn lookup_is_case_insensitive() {
        let lexicon = Lexicon::parse(EN);

        assert_eq!(lexicon.support("Hello"), Support::Exact { rank: 12 });
    }

    #[test]
    fn an_empty_fragment_tells_nothing() {
        let lexicon = Lexicon::parse(EN);

        assert_eq!(lexicon.support(""), Support::None);
    }

    #[test]
    fn the_set_falls_back_to_none_for_an_unknown_language() {
        let set = LexiconSet::from_files(&[("en", EN), ("ru", RU)]);

        assert_eq!(set.support("en", "the"), Support::Exact { rank: 1 });
        assert_eq!(set.support("ru", "привет"), Support::Exact { rank: 7 });
        assert_eq!(set.support("fr", "le"), Support::None);
    }

    #[test]
    fn missing_files_are_skipped_instead_of_failing() {
        let set = LexiconSet::from_files(&[("en", EN), ("ru", "   \n")]);

        assert_eq!(set.len(), 1);
        assert!(set.contains("en"));
        assert!(!set.contains("ru"));
    }
}
